class Solution:

	def dfs(self, matrix, N, M, i, j):
		matrix[i][j] = 0
		if i in (0, N - 1) or j in (0, M - 1):
			return False
		flag1 = True
		flag2 = True
		flag3 = True
		flag4 = True
		if i >= 1 and matrix[i - 1][j]:
			flag1 = self.dfs(matrix, N, M, i - 1, j)
		if i <= N - 1 and matrix[i + 1][j]:
			flag2 = self.dfs(matrix, N, M, i + 1, j)
		if j >= 1 and matrix[i][j - 1]:
			flag3 = self.dfs(matrix, N, M, i, j - 1)
		if j <= M - 1 and matrix[i][j + 1]:
			flag4 = self.dfs(matrix, N, M, i, j + 1)
		return flag1 and flag2 and flag3 and flag4

	def closedIslands(self, matrix, N, M):
		count = 0
		for i in range(1, N - 1):
			for j in range(1, M - 1):
				if matrix[i][j] == 1 and self.dfs(matrix, N, M, i, j):
					count += 1
		return count
